partial class Canvas{
 public void TestVectorRegionSelection(){
  SetSelectionMode("Lasso selection");OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,20,20,0));foreach(var p in new[]{new Point(180,20),new Point(180,130),new Point(20,130),new Point(20,20)})OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,p.X,p.Y,0));OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,20,20,0));if(selectedPaths.Count!=1||selectedVector.Points[0].X!=40)throw new Exception("Vector lasso actual gesture");
  SetSelectionMode("Polygon selection");foreach(var p in new[]{new Point(220,150),new Point(390,150),new Point(390,260),new Point(220,260)})TestDrag(p,p);TestRightClick();if(selectedPaths.Count!=1||selectedVector.Points[0].X!=250)throw new Exception("Vector polygon right click");
  using(var path=new GraphicsPath()){path.AddRectangle(new Rectangle(20,20,160,110));SelectPathsInRegion(path,1);if(selectedPaths.Count!=2)throw new Exception("Vector region add");SelectPathsInRegion(path,-1);if(selectedPaths.Count!=1||selectedVector.Points[0].X!=250)throw new Exception("Vector region subtract");}
  SetSelectionMode("Draw");
 }
 void SelectPathsInRegion(GraphicsPath boundary,int operation){
  if(operation==0)ClearSelectedPaths();using(var selection=new Region(boundary))using(var identity=new Matrix())foreach(var shape in Doc.Selected.Vectors){bool hit=false;using(var path=shape.Path()){if(path.PointCount<2)continue;if(shape.HasFill)using(var filled=new Region(path)){filled.Intersect(selection);hit=filled.GetRegionScans(identity).Length>0;}if(!hit)using(var stroke=(GraphicsPath)path.Clone())using(var pen=new Pen(Color.Black,Math.Max(1,shape.Width))){stroke.Widen(pen);using(var outline=new Region(stroke)){outline.Intersect(selection);hit=outline.GetRegionScans(identity).Length>0;}}}if(!hit)continue;foreach(var member in Doc.Selected.Vectors.Where(v=>v==shape||shape.GroupId!=""&&v.GroupId==shape.GroupId)){if(operation<0)RemoveSelectedPath(member);else AddSelectedPath(member);}}
  ExpandSelectedGroups();selectedVector=Doc.Selected.Vectors.LastOrDefault(v=>selectedPaths.Contains(v));selectedPoints.Clear();if(selectedVector!=null&&VectorSelected!=null)VectorSelected();NotifyPointSelection();Invalidate();
 }
 void AddSymmetricVectors(VectorShape source){
  var map=new SymmetryMap(Doc.Width,Doc.Height,VerticalMirror,HorizontalMirror,RadialSymmetry,RadialRepeats);Doc.Selected.Vectors.Add(source);
  for(int index=1;index<map.Count;index++){var copy=source.Copy();if(copy.Kind=="Ellipse"&&copy.Points.Count==2){PointF c,u,v;copy.EllipseAxes(out c,out u,out v);copy.StoreAxes(c,u,v);}copy.Points=copy.Points.Select(p=>map.Transform(p,index)).ToList();PointF origin=map.Transform(PointF.Empty,index);foreach(int point in copy.Handles.Keys.ToArray())copy.Handles[point]=copy.Handles[point].Select(h=>{var q=map.Transform(h,index);return new PointF(q.X-origin.X,q.Y-origin.Y);}).ToArray();Doc.Selected.Vectors.Add(copy);}
 }
}
